# Generated by OrchestKit Claude Plugin
# Created: 2026-07-06

"""Correct Company "Portfolio Size" from associated Locations' "SF Occupied".

Portfolio Size on a Company must equal the sum of the SF Occupied values of
all Locations linked to that Company (via the Location -> Company record
reference). The sync:

1. Scans all Location records once, aggregating SF Occupied per Company.
2. Fetches current Portfolio Size for every Company with >= 1 Location in
   batches (record_id $in filter — no per-company N+1 requests).
3. Updates only Companies whose stored value differs from the computed sum,
   appending every decision to an append-only JSONL audit log.

Safety:
- Dry-run mode prints and audits intended changes without writing.
- Companies whose Locations ALL lack an SF Occupied value are skipped by
  default (no evidence to write; a stored value is never clobbered with 0).
- Reruns are idempotent: already-correct companies are skipped.
"""

import time
from typing import Any, Dict, List, Optional

from .client import Client
from .utils import append_audit_entry, extract_record_id, get_first_value

# Workspace-specific default slugs (see attio-workspace-schema skill)
PORTFOLIO_SIZE_ATTR = "portfolio_size_1749271992"
SF_OCCUPIED_ATTR = "sf_occupied"
LOCATION_COMPANY_ATTR = "company"


def first_number(values: Dict[str, Any], attr: str) -> Optional[float]:
    """Extract a numeric attribute value from an Attio value array."""
    raw = values.get(attr)
    if isinstance(raw, list) and raw:
        item = raw[0]
        value = item.get("value") if isinstance(item, dict) else item
        if value is not None:
            try:
                return float(value)
            except (TypeError, ValueError):
                return None
    return None


def aggregate_locations(
    client: Client,
    location_object: str,
    page_size: int,
    sf_attr: str = SF_OCCUPIED_ATTR,
    company_attr: str = LOCATION_COMPANY_ATTR,
) -> Dict[str, Dict[str, Any]]:
    """Scan all locations once, summing SF Occupied per linked company.

    Returns {company_id: {"sum": float, "locations": int, "with_sf": int}}.
    """
    per_company: Dict[str, Dict[str, Any]] = {}
    scanned = 0
    orphans = 0

    for location in client.paginate_records(location_object, page_size=page_size):
        scanned += 1
        values = location.get("values", {}) or {}
        company_refs = values.get(company_attr) or []
        company_id = None
        if isinstance(company_refs, list) and company_refs:
            company_id = company_refs[0].get("target_record_id")
        if not company_id:
            orphans += 1
            continue

        sf = first_number(values, sf_attr)
        entry = per_company.setdefault(
            company_id, {"sum": 0.0, "locations": 0, "with_sf": 0}
        )
        entry["locations"] += 1
        if sf is not None:
            entry["sum"] += sf
            entry["with_sf"] += 1

        if scanned % 500 == 0:
            print(f"Scanned {scanned} locations across {len(per_company)} companies...")

    print(
        f"Scanned {scanned} locations: {len(per_company)} companies linked, "
        f"{orphans} locations without a company link"
    )
    return per_company


def fetch_companies_batch(
    client: Client, company_object: str, company_ids: List[str]
) -> List[Dict[str, Any]]:
    """Fetch companies by ID using the record_id $in filter (batched)."""
    payload = {
        "filter": {"record_id": {"$in": company_ids}},
        "limit": len(company_ids),
    }
    return client.list_records(company_object, payload).get("data", [])


def update_portfolio_sizes(
    client: Client,
    company_object: str,
    location_object: str,
    page_size: int,
    batch_size: int,
    dry_run: bool,
    write_zero_when_unknown: bool,
    per_update_sleep_s: float,
    audit_file: Optional[str] = None,
    portfolio_attr: str = PORTFOLIO_SIZE_ATTR,
) -> int:
    """Run the correction. Returns a process exit code (0 clean, 1 failures)."""
    per_company = aggregate_locations(client, location_object, page_size)
    if not per_company:
        print("No companies with locations found; nothing to do.")
        return 0

    company_ids = list(per_company.keys())
    checked = 0
    already_correct = 0
    updates_made = 0
    skipped_unknown = 0
    failures = 0

    for start in range(0, len(company_ids), batch_size):
        batch_ids = company_ids[start : start + batch_size]
        try:
            companies = fetch_companies_batch(client, company_object, batch_ids)
        except Exception as e:
            failures += len(batch_ids)
            print(f"‼️ Failed to fetch company batch ({len(batch_ids)} ids): {e}")
            append_audit_entry(
                audit_file,
                {
                    "action": "batch_fetch_failed",
                    "company_ids": batch_ids,
                    "error": str(e),
                },
            )
            continue

        fetched_ids = set()
        for company in companies:
            company_id = extract_record_id(company)
            if not company_id or company_id not in per_company:
                continue
            fetched_ids.add(company_id)
            checked += 1

            values = company.get("values", {}) or {}
            company_name = get_first_value(values, "name")
            current = first_number(values, portfolio_attr)
            agg = per_company[company_id]
            expected = agg["sum"]

            audit_base = {
                "company_id": company_id,
                "company_name": company_name,
                "current_portfolio_size": current,
                "expected_portfolio_size": expected,
                "location_count": agg["locations"],
                "locations_with_sf": agg["with_sf"],
            }

            # No SF data at all: writing 0 would clobber without evidence.
            if agg["with_sf"] == 0 and not write_zero_when_unknown:
                skipped_unknown += 1
                append_audit_entry(
                    audit_file, {"action": "skipped_no_sf_data", **audit_base}
                )
                continue

            if current is not None and abs(current - expected) < 1e-6:
                already_correct += 1
                continue

            if dry_run:
                updates_made += 1
                print(
                    f"DRY-RUN: {company_name} ({company_id}): "
                    f"{current} -> {expected} ({agg['locations']} locations)"
                )
                append_audit_entry(audit_file, {"action": "dry_run", **audit_base})
                continue

            payload = {"data": {"values": {portfolio_attr: [{"value": expected}]}}}
            try:
                client.update_record(company_object, company_id, payload)
                updates_made += 1
                print(
                    f"✅ {company_name} ({company_id}): {current} -> {expected} "
                    f"({agg['locations']} locations)"
                )
                append_audit_entry(audit_file, {"action": "updated", **audit_base})
                if per_update_sleep_s > 0:
                    time.sleep(per_update_sleep_s)
            except Exception as e:
                failures += 1
                print(f"‼️ Failed to update {company_name} ({company_id}): {e}")
                append_audit_entry(
                    audit_file,
                    {"action": "update_failed", "error": str(e), **audit_base},
                )

        for missing_id in set(batch_ids) - fetched_ids:
            failures += 1
            print(f"‼️ Company {missing_id} not returned by batch query")
            append_audit_entry(
                audit_file, {"action": "company_missing", "company_id": missing_id}
            )

    verb = "Would update" if dry_run else "Updated"
    print(
        f"\nChecked {checked}/{len(company_ids)} companies. {verb} {updates_made}. "
        f"Already correct: {already_correct}. Skipped (no SF data): {skipped_unknown}. "
        f"Failures: {failures}."
    )
    if failures:
        print("‼️ Completed with failures — rerun to retry (updates are idempotent)")
        return 1
    return 0
